 JSONObject account()throws Exception {JSONObject r=new JSONObject().put("loggedIn",false);try(Cursor c=context.getContentResolver().query(ACCOUNTS,new String[]{"uid","clusterId"},"loggedIn=1",null,null)){if(c==null)throw new UserError(R.string.error_native_account_provider_unavailable);if(c.getCount()>1)throw new UserError(R.string.error_multiple_active_native_accounts);if(c.moveToFirst())r.put("loggedIn",true).put("uid",c.getString(0)).put("clusterId",c.getString(1));}return r;}
 String fingerprint()throws Exception {ArrayList<String> rows=new ArrayList<>();try(Cursor c=context.getContentResolver().query(Uri.parse("content://com.onyx.android.sdk.note.ContentProvider/NoteModel"),new String[]{"uniqueId","type","status","userId"},null,null,null)){if(c==null)throw new UserError(R.string.error_native_library_unavailable);while(c.moveToNext())rows.add(c.getString(0)+":"+c.getInt(1)+":"+c.getInt(2)+":"+c.getString(3));}Collections.sort(rows);return hex(java.security.MessageDigest.getInstance("SHA-256").digest(String.join("\n",rows).getBytes(StandardCharsets.UTF_8)));}
 static String hex(byte[] b){StringBuilder s=new StringBuilder();for(byte v:b)s.append(String.format(Locale.ROOT,"%02x",v&255));return s.toString();}
 private final class Binding implements AutoCloseable {final Handler main=new Handler(Looper.getMainLooper());final CompletableFuture<IBinder> future=new CompletableFuture<>();boolean bound;final ServiceConnection conn=new ServiceConnection(){public void onServiceConnected(ComponentName n,IBinder b){future.complete(b);}public void onServiceDisconnected(ComponentName n){future.completeExceptionally(new UserError(R.string.error_native_service_disconnected));}public void onNullBinding(ComponentName n){future.completeExceptionally(new UserError(R.string.error_native_binding_unavailable));}};Binding(){main.post(()->{try{bound=context.bindService(new Intent().setComponent(new ComponentName("com.onyx.android.ksync","com.onyx.android.ksync.service.KSyncService")),conn,Context.BIND_AUTO_CREATE);if(!bound)future.completeExceptionally(new UserError(R.string.error_native_service_denied_binding));}catch(Exception e){future.completeExceptionally(e);}});}IBinder get()throws Exception {IBinder b=future.get(15,TimeUnit.SECONDS);if(!SERVICE.equals(b.getInterfaceDescriptor()))throw new UserError(R.string.error_unexpected_native_interface);return b;}public void close(){main.post(()->{if(bound){context.unbindService(conn);bound=false;}});}}
 void clusterCall(int transaction,String id)throws Exception {requireKsyncAvailable();if(id!=null&&!id.matches("[a-zA-Z0-9_-]{1,80}"))throw new UserError(R.string.error_invalid_cluster_identity);CompletableFuture<Integer> done=new CompletableFuture<>();Binder callback=new Binder(){protected boolean onTransact(int code,Parcel p,Parcel reply,int flags)throws RemoteException {if(code==INTERFACE_TRANSACTION){if(reply!=null)reply.writeString("com.onyx.android.sdk.sync.ksync.service.SyncClusterCallback");return true;}if(code!=1)return super.onTransact(code,p,reply,flags);p.enforceInterface("com.onyx.android.sdk.sync.ksync.service.SyncClusterCallback");if(p.readInt()==0)done.completeExceptionally(new UserError(R.string.error_empty_native_cluster_callback));else{p.readString();done.complete(p.readInt());}if(reply!=null)reply.writeNoException();return true;}};try(Binding b=new Binding()){Parcel p=Parcel.obtain();try{p.writeInterfaceToken(SERVICE);p.writeInt(1);p.writeString(id);p.writeInt(2);p.writeStrongBinder(callback);if(!b.get().transact(transaction,p,null,IBinder.FLAG_ONEWAY))throw new UserError(R.string.error_cluster_switch_unsupported);}finally{p.recycle();}if(done.get(45,TimeUnit.SECONDS)!=2)throw new UserError(R.string.error_native_cluster_switch_failed);}}
 void updateClusters()throws Exception {clusterCall(81,null);}
 void switchCluster(String id)throws Exception {clusterCall(80,id);long end=System.nanoTime()+TimeUnit.SECONDS.toNanos(30);while(!id.equals(read(CLUSTER).getString("curClusterId"))){if(System.nanoTime()>end)throw new UserError(R.string.error_native_selected_cluster_differs);Thread.sleep(300);}}
 void login(String account,String code,boolean master)throws Exception {requireKsyncAvailable();CompletableFuture<Integer> done=new CompletableFuture<>();Binder cb=new Binder(){protected boolean onTransact(int c,Parcel p,Parcel reply,int f)throws RemoteException {if(c==INTERFACE_TRANSACTION){if(reply!=null)reply.writeString("com.onyx.android.sdk.sync.ksync.service.AccountIntentCallback");return true;}if(c!=1)return super.onTransact(c,p,reply,f);p.enforceInterface("com.onyx.android.sdk.sync.ksync.service.AccountIntentCallback");if(p.readInt()==0)done.completeExceptionally(new UserError(R.string.error_empty_account_callback));else{p.readString();p.readString();p.readString();p.readInt();p.readString();p.readString();p.readString();p.readString();int status=p.readInt();p.readLong();p.readInt();p.readInt();p.readString();done.complete(status);}if(reply!=null)reply.writeNoException();return true;}};try(Binding b=new Binding()){Parcel p=Parcel.obtain();try{p.writeInterfaceToken(SERVICE);p.writeInt(1);p.writeString(master?null:account);p.writeString(master?null:code);p.writeString(null);p.writeInt(master?21:1);p.writeString(null);p.writeString("PowerSync");p.writeString(null);p.writeString(null);p.writeInt(0);p.writeLong(0);p.writeInt(master?0:2);p.writeInt(0);p.writeString(null);p.writeStrongBinder(cb);if(!b.get().transact(65,p,null,IBinder.FLAG_ONEWAY))throw new UserError(R.string.error_native_login_unsupported);}finally{p.recycle();}int result=done.get(60,TimeUnit.SECONDS);if(result!=0)throw new UserError(R.string.error_native_sign_in_failed,result);}}
 JSONArray catalog()throws Exception {JSONArray a=new JSONArray();try(Cursor c=context.getContentResolver().query(Uri.parse("content://com.onyx.content.database.ContentProvider/Metadata"),null,null,null,null)){if(c==null)throw new UserError(R.string.error_reader_catalog_unavailable);while(c.moveToNext()){if(a.length()>10000)throw new UserError(R.string.error_reader_catalog_exceeds_snapshot_limit);JSONObject row=new JSONObject();for(int i=0;i<c.getColumnCount();i++){Object v=switch(c.getType(i)){case Cursor.FIELD_TYPE_NULL -> JSONObject.NULL;case Cursor.FIELD_TYPE_INTEGER -> c.getLong(i);case Cursor.FIELD_TYPE_FLOAT -> c.getDouble(i);case Cursor.FIELD_TYPE_STRING -> c.getString(i);default -> throw new UserError(R.string.error_unsupported_catalog_value);};row.put(c.getColumnName(i),v);}a.put(row);}}return a;}
 JSONObject catalogFiles(JSONArray catalog)throws Exception {
  return CatalogRecovery.fileAvailability(catalog,path->!path.isEmpty()&&new File(path).isFile());
 }
 int repairMissingCatalog(JSONArray before)throws Exception {
  Uri uri=Uri.parse("content://com.onyx.content.database.ContentProvider/Metadata");
  return CatalogRecovery.restore(before,new CatalogRecovery.Store() {
   public JSONArray read()throws Exception {return catalog();}
   public void insert(JSONObject row)throws Exception {
    // Recheck both identities immediately before insertion. Never replace live rows.
    try(Cursor c=context.getContentResolver().query(uri,new String[]{"id"},"id=? OR uuid=?",new String[]{String.valueOf(row.get("id")),row.getString("uuid")},null)) {
     if(c==null||c.moveToFirst())throw new UserError(R.string.error_original_catalog_id_unavailable_for_repair);
    }
    ContentValues values=new ContentValues();
    for(Iterator<String> keys=row.keys();keys.hasNext();) {
     String key=keys.next();Object value=row.get(key);
     if(value==JSONObject.NULL)values.putNull(key);
     else if(value instanceof Integer||value instanceof Long)values.put(key,((Number)value).longValue());
     else if(value instanceof Number)values.put(key,((Number)value).doubleValue());
     else if(value instanceof String)values.put(key,(String)value);
     else throw new UserError(R.string.error_unsupported_catalog_field);
    }
    if(context.getContentResolver().insert(uri,values)==null)throw new UserError(R.string.error_reader_catalog_repair_failed);
   }
  });
 }
 boolean restoreAccount(JSONObject previous,String nativeUid)throws Exception {if(!previous.optBoolean("loggedIn"))return !account().optBoolean("loggedIn");String wanted=previous.getString("uid");if(wanted.equals(account().optString("uid")))return true;if(!"Go103_2Lumi".equals(Build.MODEL))return false;int matches=0,total=0;try(Cursor c=context.getContentResolver().query(ACCOUNTS,new String[]{"uid"},"(parent IS NULL OR parent='') AND uid<>?",new String[]{nativeUid},null)){if(c==null)return false;while(c.moveToNext()){total++;if(wanted.equals(c.getString(0)))matches++;}}if(total!=1||matches!=1)return false;context.getContentResolver().delete(ACCOUNTS,"uid=?",new String[]{nativeUid});login(null,null,true);return wanted.equals(account().optString("uid"));}

